/**
 * Every emoji there is, as data.
 *
 * Generated — do not edit by hand. `tools` is not in this repository: the file
 * is built from two published tables, both MIT, and the generator and its
 * inputs live outside the project on purpose (see
 * `XELVIC_MOBILE_FEATURE_INVENTORY.md`). To rebuild it, re-run the generator
 * described at the top of `src/features/emoji/data.ts`'s README entry — the
 * tables are `unicode-emoji-json` (names, groups, skin-tone support) and
 * `emoji-datasource` (the short names people search by).
 *
 * Each row is
 * `[character, name, group, takesATone, hasStill, hasMotion, searchWords, tonedMasks]`,
 * where the group is an index into `EMOJI_GROUPS`, `hasStill` and
 * `hasMotion` say whether Google draws that emoji and whether Google animates
 * it, `searchWords` carries the words the English name does not already
 * contain, and `tonedMasks` is ten digits for an emoji that takes a skin tone
 * — its five tinted drawings, then its five tinted animations — and empty for
 * one that does not.
 *
 * 1906 emoji across 9 groups — 1892 of them with a
 * drawing and 605 of them with an animation, counted by asking Google's
 * own emoji CDN for each one before this file was written rather than assumed,
 * and 323 of them take a skin tone, whose 1580 tinted drawings
 * and 250 tinted animations were counted the same way.
 *
 * The list is the whole of Unicode's emoji, including the ones a person's own
 * device may draw as a box: every tile is drawn with Google's art, so a missing
 * system font is not a missing emoji here. Google animates about a third of
 * them, and those are the tiles that move.
 */

export const EMOJI_GROUPS = [
  "Smileys & Emotion",
  "People & Body",
  "Animals & Nature",
  "Food & Drink",
  "Travel & Places",
  "Activities",
  "Objects",
  "Symbols",
  "Flags",
] as const;

/**
 * `[character, name, group, takesATone, hasStill, hasMotion, searchWords, tonedMasks]`
 *
 * `tonedMasks` is `""` for an emoji no tone can be put on, and otherwise ten
 * digits: the five tinted drawings in Unicode's tone order, then the five
 * tinted animations. `artOf` in `model.ts` is what reads it.
 */
export type EmojiRow = readonly [
  string,
  string,
  number,
  0 | 1,
  0 | 1,
  0 | 1,
  string,
  string,
];

